import { ArrowBigUp, Scroll } from 'lucide-react'
import React from 'react'

const ScrollToTop = () => {
  return <div className='fixed bottom-16 right-16 z-100 border-2 rounded-full w-16 h-16 flex justify-center items-center bg-text/30 hover:bg-text/50  cursor-pointer '>
    <button onClick={()=> window.scrollTo({top:0,behavior:"smooth"})}> <ArrowBigUp className='w-8 h-8'/></button>
  </div>
}

export default ScrollToTop;
